pattern.forbidden_reflex:
>bg: #111827;
rect #card {
  at: below #prev offset: 16px;
  text "MRR" { size: 24px; }
}

pattern.verified_toad_code:
>cardBg = #111827;
>borderSubtle = #33415550;
>accentGreen = #10b981;

rect #kpiCard {
  at: below #prevCard offset 24px;
  size: 320px 150px;
  fill: >cardBg;
  stroke: >borderSubtle 1px solid;
  border-radius: 14px;
  shadow: 0 10px 25px #00000040;

  text #kpiLabel {
    at: top-left of parent offset 20px 20px;
    content: "MONTHLY RECURRING REVENUE";
    font-family: "Inter, sans-serif";
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.5px;
    color: #64748b;
  }

  text #kpiValue {
    at: below #kpiLabel offset 8px;
    content: "$128,450";
    font-family: "Inter, sans-serif";
    font-size: 32px;
    font-weight: 800;
    color: #f8fafc;
  }

  rect #trendPill {
    at: below #kpiValue offset 12px;
    size: 88px 26px;
    fill: #10b98120;
    border-radius: 9999px;

    text {
      at: center of parent;
      content: "+14.8%";
      font-family: "Inter, sans-serif";
      font-size: 11px;
      font-weight: 700;
      color: >accentGreen;
    }
  }
}
